package com.arqly.backend.entity; import jakarta.persistence.*;import java.math.*;import java.time.*;
@Entity @Table(name="financial_entries") public class FinancialEntry extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="tenant_id",nullable=false)private Tenant tenant;@Enumerated(EnumType.STRING)@Column(nullable=false)private FinancialEntryType type;@Column(nullable=false)private String description;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="client_id")private Client client;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="project_id")private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="proposal_id")private Proposal proposal;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="category_id")private FinancialCategory category;private String counterpartyName;@Column(nullable=false,precision=15,scale=2)private BigDecimal totalAmount=BigDecimal.ZERO;private LocalDate issueDate;private LocalDate competenceDate;@Enumerated(EnumType.STRING)@Column(nullable=false)private FinancialEntryStatus status=FinancialEntryStatus.OPEN;@Column(columnDefinition="text")private String notes;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="created_by_id")private TenantUser createdBy;@Column(nullable=false)private boolean clientVisible=false;@Column(nullable=false)private boolean deleted=false;private Instant deletedAt;public Tenant getTenant(){return tenant;}public void setTenant(Tenant v){tenant=v;}public FinancialEntryType getType(){return type;}public void setType(FinancialEntryType v){type=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public Client getClient(){return client;}public void setClient(Client v){client=v;}public Project getProject(){return project;}public void setProject(Project v){project=v;}public Proposal getProposal(){return proposal;}public void setProposal(Proposal v){proposal=v;}public FinancialCategory getCategory(){return category;}public void setCategory(FinancialCategory v){category=v;}public String getCounterpartyName(){return counterpartyName;}public void setCounterpartyName(String v){counterpartyName=v;}public BigDecimal getTotalAmount(){return totalAmount;}public void setTotalAmount(BigDecimal v){totalAmount=v;}public LocalDate getIssueDate(){return issueDate;}public void setIssueDate(LocalDate v){issueDate=v;}public LocalDate getCompetenceDate(){return competenceDate;}public void setCompetenceDate(LocalDate v){competenceDate=v;}public FinancialEntryStatus getStatus(){return status;}public void setStatus(FinancialEntryStatus v){status=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}public TenantUser getCreatedBy(){return createdBy;}public void setCreatedBy(TenantUser v){createdBy=v;}public boolean isClientVisible(){return clientVisible;}public void setClientVisible(boolean v){clientVisible=v;}public boolean isDeleted(){return deleted;}public void setDeleted(boolean v){deleted=v;}public Instant getDeletedAt(){return deletedAt;}public void setDeletedAt(Instant v){deletedAt=v;}}
